    check(succeeded.returncode == 0, succeeded.stdout + succeeded.stderr)
    stable = subprocess.check_output([
        "git", "-C", REPO, "rev-parse", "refs/bwr/test-run/lot-1/task-1",
    ], text=True).strip()
    check(
        stable == candidate,
        succeeded.stdout + succeeded.stderr,
    )


