@test
def in_process_runner_matches_real_note_and_refusal_results():
    real = run_progress_process("note", "ruling", "--text", "same authority")
    check(real.returncode == 0, real.stdout + real.stderr)
    real_entry = journal_lines()[0]
    reset()

    local = run_progress("note", "ruling", "--text", "same authority")
    check(local.returncode == 0, local.stdout + local.stderr)
    local_entry = journal_lines()[0]
    for entry in (real_entry, local_entry):
        entry.pop("ts", None)
    check(local_entry == real_entry,
          "the in-process runner changed the durable note account")

    reset()
    real_refusal = run_progress_process("note", "ruling", "--data", "[]")
    reset()
    local_refusal = run_progress("note", "ruling", "--data", "[]")
    check(real_refusal.returncode != 0 and local_refusal.returncode != 0,
          "one runner accepted malformed note data")
    check("--data` must be a JSON object" in real_refusal.stdout
          and "--data` must be a JSON object" in local_refusal.stdout,
          "the runners disagree on the malformed note refusal")
    check(journal_lines() == [], "an in-process refusal changed the journal")


@test
def fixture_snapshot_restores_one_isolated_real_prefix():
    def build_prefix():
        seed_active_attempt()
        recorded = run_progress("note", "ruling", "--text", "snapshot authority")
        check(recorded.returncode == 0, recorded.stdout + recorded.stderr)

    restore_fixture_snapshot("active-attempt", build_prefix)
    journal_path = os.path.join(WORKSPACE, "progress.jsonl")
    exact = open(journal_path, "rb").read()
    with open(journal_path, "ab") as target:
        target.write(b'{"snapshot":"changed"}\n')

    restore_fixture_snapshot("active-attempt", build_prefix)
    check(open(journal_path, "rb").read() == exact,
          "the fixture snapshot retained another test's journal mutation")
    replay = run_progress("construction-verdict-check", "history")
    check(replay.returncode == 0, replay.stdout + replay.stderr)


@test
def fixture_reset_restores_one_pristine_repository():
    baseline_status = subprocess.check_output(
        ["git", "-C", REPO, "status", "--porcelain"], text=True,
    )
    leaked = write_project("fixture-reset-leak.txt", "must not survive\n")
    subprocess.run(["git", "-C", REPO, "add", leaked], check=True)
    reset()
    check(not os.path.exists(leaked), "the shared reset retained a fixture-owned path")
    status = subprocess.check_output(
        ["git", "-C", REPO, "status", "--porcelain"], text=True,
    )
    check(status == baseline_status, f"the shared reset retained repository state: {status}")


@test
def format_slowest_tests_orders_descending():
    check(
        format_slowest_tests([(0.2, "fast"), (1.5, "slow")], limit=2)
        == ["1.500s slow", "0.200s fast"],
        "the functional duration report is not ordered from slowest to fastest",
    )


def format_slowest_tests(durations, limit=10):
    return [
        f"{seconds:.3f}s {name}"
        for seconds, name in sorted(durations, reverse=True)[:limit]
    ]


